// ═══ RULE 1: PROGRAM ORDER ═══
int x = 1;   // A
int y = 2;   // B — A happens-before B (same thread)
// Within ONE thread: everything is in order. (But JIT may reorder if no dependency!)

// ═══ RULE 2: MONITOR LOCK (synchronized) ═══
synchronized (lock) {
    sharedData = 42;         // write inside sync
}                             // UNLOCK — happens-before:

synchronized (lock) {         // LOCK — sees all writes before previous unlock!
    int x = sharedData;       // guaranteed to see 42!
}

// ═══ RULE 3: VOLATILE WRITE → READ ═══
volatile boolean ready = false;
int data = 0;

// Thread-1:
data = 42;                    // non-volatile write
ready = true;                 // volatile WRITE — happens-before:

// Thread-2:
if (ready) {                  // volatile READ — sees everything before the write!
    int x = data;             // guaranteed 42! (transitivity: data write HB ready write HB ready read)
}

// ═══ RULE 4: Thread.start() ═══
data = 42;
Thread t = new Thread(() -> {
    int x = data;             // guaranteed 42! start() creates happens-before!
});
t.start();                    // everything before start() HB thread body!

// ═══ RULE 5: Thread.join() ═══
Thread t = new Thread(() -> {
    sharedResult = 42;        // write inside thread
});
t.start();
t.join();                     // happens-before: everything in t visible here!
int x = sharedResult;         // guaranteed 42!

// ═══ RULE 6: CONSTRUCTOR (final fields) ═══
class Account {
    final String id;
    Account(String id) { this.id = id; }
}
Account a = new Account("SAV2001");
// When constructor completes: final fields frozen!
// Any thread seeing reference 'a' sees id = "SAV2001"!

// ═══ RULE 7: TRANSITIVITY ═══
// A HB B, B HB C → A HB C!
// Thread-1: data = 42; (A) → volatile ready = true; (B)
// Thread-2: if (ready) (C) → int x = data; (D)
// A HB B (program order). B HB C (volatile). C HB D (program order).
// → A HB D (transitivity!) → data = 42 visible at D!

// ═══ WITHOUT HAPPENS-BEFORE: stale reads ═══
int shared = 0;  // no volatile, no synchronized
// Thread-1: shared = 42;
// Thread-2: while (shared == 0) { } // may loop FOREVER!
// No happens-before → JIT caches shared in register → never sees 42!
