// ─── File: src/test/java/com/bank/hb/HappensBeforeTest.java ───
package com.bank.hb;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class HappensBeforeTest {

    // ═══ RULE 2: synchronized unlock → lock ═══
    @Test
    void synchronizedHB() throws InterruptedException {
        int[] data = {0};
        Object lock = new Object();
        CountDownLatch written = new CountDownLatch(1);

        new Thread(() -> {
            synchronized (lock) { data[0] = 42; }
            written.countDown();
        }).start();
        written.await();

        synchronized (lock) {
            assertThat(data[0]).isEqualTo(42);  // guaranteed by HB!
        }
    }

    // ═══ RULE 3: volatile write → read ═══
    @Test
    void volatileHB() throws InterruptedException {
        int[] data = {0};
        volatile boolean[] ready = {false};  // can't make local volatile, using array

        // Using AtomicBoolean as volatile proxy:
        java.util.concurrent.atomic.AtomicBoolean atomicReady = new java.util.concurrent.atomic.AtomicBoolean(false);

        new Thread(() -> {
            data[0] = 42;                // non-volatile write
            atomicReady.set(true);       // volatile-like write (HB edge!)
        }).start();

        while (!atomicReady.get()) Thread.yield();
        assertThat(data[0]).isEqualTo(42);  // visible! Transitivity: data write HB ready write HB ready read HB data read!
    }

    // ═══ RULE 4: start() HB thread body ═══
    @Test
    void startHB() throws InterruptedException {
        int[] data = {0};
        data[0] = 42;  // before start()!

        Thread t = new Thread(() -> {
            assertThat(data[0]).isEqualTo(42);  // visible! start() creates HB!
        });
        t.start();
        t.join();
    }

    // ═══ RULE 5: thread body HB join() ═══
    @Test
    void joinHB() throws InterruptedException {
        int[] result = {0};
        Thread t = new Thread(() -> result[0] = 42);
        t.start();
        t.join();  // HB: everything in t visible here!
        assertThat(result[0]).isEqualTo(42);  // guaranteed!
    }

    // ═══ RULE 7: Transitivity ═══
    @Test
    void transitivityHB() throws InterruptedException {
        int[] a = {0};
        int[] b = {0};
        Object lock = new Object();

        new Thread(() -> {
            a[0] = 1;  // A
            synchronized (lock) { b[0] = 2; }  // B
        }).start();

        Thread.sleep(100);

        synchronized (lock) {  // C (HB: B → C via monitor)
            // A HB B (program order). B HB C (monitor). → A HB C (transitivity!)
            assertThat(b[0]).isEqualTo(2);
            assertThat(a[0]).isEqualTo(1);  // visible via transitivity!
        }
    }
}
